function formatDate(value: Date | string | number) { return new Date(value).toLocaleString(undefined, { dateStyle: "medium", timeStyle: "short" }); }
export function formatAutosaveTimestamp(value: Date | string | number) { return new Date(value).toLocaleString(undefined, { dateStyle: "medium", timeStyle: "medium" }); }
export function formatAdminDate(value: Date | string | number, timezone: TimezoneOption, dateFormat: DateFormatOption) { const date = new Date(value); if (dateFormat === "iso") { const parts = new Intl.DateTimeFormat("en-CA", { timeZone: timezone === "local" ? undefined : timezone, year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false }).formatToParts(date).reduce<Record<string, string>>((result, part) => { result[part.type] = part.value; return result; }, {}); return `${parts.year}-${parts.month}-${parts.day} ${parts.hour}:${parts.minute}:${parts.second}`; } return new Intl.DateTimeFormat(undefined, { dateStyle: dateFormat === "short" ? "short" : "medium", timeStyle: "medium", timeZone: timezone === "local" ? undefined : timezone }).format(date); }
function downloadBase64(contentBase64: string, filename: string, mime: string) { const bytes = Uint8Array.from(atob(contentBase64), (char) => char.charCodeAt(0)); const url = URL.createObjectURL(new Blob([bytes], { type: mime })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = filename; anchor.click(); URL.revokeObjectURL(url); }
export function validatePdfSelection(file: Pick<File, "type" | "name" | "size">) { if (file.type !== "application/pdf" && !file.name.toLowerCase().endsWith(".pdf")) return "invalidType" as const; if (file.size > 12 * 1024 * 1024) return "tooLarge" as const; return null; }
export function sortBookingRows<T extends { createdAt: Date | string; status: string }>(rows: T[], sortMode: SortMode) { return [...rows].sort((left, right) => { if (sortMode.startsWith("date")) { const delta = new Date(left.createdAt).getTime() - new Date(right.createdAt).getTime(); return sortMode === "date_desc" ? -delta : delta; } const delta = left.status.localeCompare(right.status); return sortMode === "status_desc" ? -delta : delta; }); }
export function matchesClientSearch(row: Pick<PreviewRow, "name" | "email"> & { birthCity?: string; birthCountry?: string; id: number }, term: string) { const normalized = term.trim().toLocaleLowerCase(); if (!normalized) return true; return [row.name, row.email, row.birthCity ?? "", row.birthCountry ?? "", String(row.id)].join(" ").toLocaleLowerCase().includes(normalized); }
export function getBulkDeliveryOutcome(sent: number, failed: number) { if (sent > 0 && failed === 0) return "success" as const; if (sent > 0 && failed > 0) return "partial" as const; return "failed" as const; }
export function matchesInterest(row: { interest: string | null }, term: string) { const normalized = term.trim().toLocaleLowerCase(); return !normalized || (row.interest ?? "").toLocaleLowerCase().includes(normalized); }
export function draftStorageKey(bookingId: number) { return `admin-client-draft:${bookingId}`; }
export function draftSavedAtStorageKey(bookingId: number) { return `admin-client-draft-saved-at:${bookingId}`; }
export function autosaveIntervalStorageKey() { return AUTOSAVE_INTERVAL_STORAGE_KEY; }
export function formatHistoryChanges(changes: string) { try { return Object.entries(JSON.parse(changes) as Record<string, { from: unknown; to: unknown }>).map(([key, value]) => `${key}: ${String(value.from ?? "—")} → ${String(value.to ?? "—")}`).join("; "); } catch { return changes; } }
export function readClientDraft(row: PreviewRow) { const fallback: ClientEditDraft = { name: row.name, email: row.email, birthDate: row.birthDate, birthTime: row.birthTime, birthCity: row.birthCity, birthCountry: row.birthCountry, language: row.language, interest: row.interest }; if (typeof window === "undefined") return { draft: fallback, restored: false, savedAt: null as number | null }; try { const saved = window.localStorage.getItem(draftStorageKey(row.id)); const savedAt = Number(window.localStorage.getItem(draftSavedAtStorageKey(row.id))) || null; if (!saved) return { draft: fallback, restored: false, savedAt }; return { draft: { ...fallback, ...(JSON.parse(saved) as Partial<ClientEditDraft>) }, restored: true, savedAt }; } catch { return { draft: fallback, restored: false, savedAt: null }; } }
async function fileToBase64(file: File) { const bytes = new Uint8Array(await file.arrayBuffer()); let binary = ""; for (let index = 0; index < bytes.length; index += 0x8000) { const chunk = bytes.subarray(index, index + 0x8000); for (let offset = 0; offset < chunk.length; offset += 1) binary += String.fromCharCode(chunk[offset]); } return btoa(binary); }

